{
  "findings": [
    {
      "ref": "[D522]",
      "area": "age_gating",
      "claim": "A parent reports that Snapchat's age verification only asks for a birth date at signup with no real checks behind it, and kids can easily fake their age.",
      "stance": "risk",
      "quote": "Snapchat requires users to be at least 13 years old, but it's actually required to under U.S. privacy laws (COPPA). In reality, Snapchat's age verification is minimal. It only asks for a birth date at signup, with no real checks behind it. Kids who want to join early can easily fake their age—and many do."
    },
    {
      "ref": "[D522]",
      "area": "age_gating",
      "claim": "A parent reports that Snapchat locks in the original birth date after teens sign up, so they can't edit it later to bypass protections.",
      "stance": "mitigation",
      "quote": "Snapchat also locks in the original birth date after teens sign up, so they can't edit it later to \"age up\" and bypass protections."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that strangers can message a teen if they are not limited to friends, and the app allows unknown adults to contact teens through mutual connections.",
      "stance": "risk",
      "quote": "They can post public Stories, but these mostly show up for friends and mutual connections, not the wider Snapchat community. Protections still limit unwanted contact from unknown adults, including tighter filters on messages, restricted friend suggestions, and private location settings. But even with safeguards, a shared connection—like a mutual friend—can still open a pathway to people they don't actually know."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that disabling Quick Add prevents the teen's profile from appearing in suggestions for people they don't know.",
      "stance": "mitigation",
      "quote": "They won't appear in Quick Add recommendations for people they don't know, which helps limit random friend requests."
    },
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "A parent reports that Snapchat collects data for ads and may share it with third parties, but the exact data collection is not detailed in the segment.",
      "stance": "neutral",
      "quote": "Content in Discover and Spotlight is filtered to reduce exposure to mature or inappropriate material, but filters are not always perfect."
    },
    {
      "ref": "[D522]",
      "area": "money",
      "claim": "A parent reports that Snapchat offers a monetization program for creators, which may pressure teens to spend money on marketed items.",
      "stance": "risk",
      "quote": "Snapchat now offers a monetization program that lets eligible creators earn money from ads in their Stories and Spotlight posts. Teens who see influencers getting paid for views may feel pressure to post more often, chase viral moments, or spend more time curating content to stand out."
    },
    {
      "ref": "[D522]",
      "area": "content",
      "claim": "A parent reports that Discover and Spotlight content is filtered to reduce exposure to mature or inappropriate material, but filters are not always perfect.",
      "stance": "neutral",
      "quote": "Content in Discover and Spotlight is filtered to reduce exposure to mature or inappropriate material, but filters are not always perfect."
    },
    {
      "ref": "[D522]",
      "area": "developer_record",
      "claim": "A parent reports that Snapchat's developer has faced criticism for weak age enforcement and lack of strong checks, which is a regulatory concern.",
      "stance": "risk",
      "quote": "Snapchat's age verification is minimal. It only asks for a birth date at signup, with no real checks behind it. Kids who want to join early can easily fake their age—and many do. This lack of strong age enforcement is one of the biggest criticisms of Snapchat and many other social apps."
    }
  ]
}
